/// Semantic text styles mapped to Dynamic Type (design/constitution.md#typography-spacing-and-shape).
enum DuckTextStyle: CaseIterable {
  /// A single prominent count or measurement.
  case display
  /// Title at the top of a page or sheet that the system bar does not draw.
  case pageTitle
  /// Heading for a group or section.
  case sectionTitle
  /// Row titles, values and running text.
  case body
  /// Descriptions and secondary row text.
  case supporting
  /// Footers, timestamps and metadata.
  case caption
  /// Labels on custom controls, tags and counts in badges.
  case label

  /// The SwiftUI font, which follows the user's text size.
  var font: Font {
    switch self {
    case .display: return .largeTitle.weight(.bold).monospacedDigit()
    case .pageTitle: return .title2.weight(.bold)
    case .sectionTitle: return .headline.weight(.semibold)
    case .body: return .body
    case .supporting: return .subheadline
    case .caption: return .footnote
    case .label: return .subheadline.weight(.semibold)
    }
  }

  var weight: PlatformFont.Weight {
    switch self {
    case .display: return .bold
    case .pageTitle: return .bold
    case .sectionTitle: return .semibold
    case .body: return .regular
    case .supporting: return .regular
    case .caption: return .regular
    case .label: return .semibold
    }
  }

  var monospacedDigits: Bool {
    switch self {
    case .display: return true
    case .pageTitle: return false
    case .sectionTitle: return false
    case .body: return false
    case .supporting: return false
    case .caption: return false
    case .label: return false
    }
  }

  var textStyle: PlatformFont.TextStyle {
    switch self {
    case .display: return .largeTitle
    case .pageTitle: return .title2
    case .sectionTitle: return .headline
    case .body: return .body
    case .supporting: return .subheadline
    case .caption: return .footnote
    case .label: return .subheadline
    }
  }

  /// The UIKit or AppKit font for the same style. UIKit fonts scale with Dynamic Type
  /// when the view sets adjustsFontForContentSizeCategory.
  var platformFont: PlatformFont {
    #if os(macOS)
    let size = NSFont.preferredFont(forTextStyle: textStyle).pointSize
    return monospacedDigits ? .monospacedDigitSystemFont(ofSize: size, weight: weight) : .systemFont(ofSize: size, weight: weight)
    #else
    let size = UIFont.preferredFont(forTextStyle: textStyle, compatibleWith: UITraitCollection(preferredContentSizeCategory: .large)).pointSize
    let base: UIFont = monospacedDigits ? .monospacedDigitSystemFont(ofSize: size, weight: weight) : .systemFont(ofSize: size, weight: weight)
    return UIFontMetrics(forTextStyle: textStyle).scaledFont(for: base)
    #endif
  }
}

extension View {
  /// Applies a semantic text style.
  func duckTextStyle(_ style: DuckTextStyle) -> some View { font(style.font) }
}

